def koszt_dostawy(razem):
    if razem >= 100:
        return 0
    elif razem >= 50:
        return 9.99
    else:
        return 14.99


for kwota in [49.99, 50, 99.99, 100, 250]:
    print(kwota, "->", koszt_dostawy(kwota))

ceny = [4.5, 2.3, 0, 7.5, 24.99]
suma = 0
ile_drogich = 0
for cena in ceny:
    if cena == 0:
        continue
    suma += cena
    if cena > 5:
        ile_drogich += 1
print(f"Suma: {suma:.2f}, droższe niż 5 zł: {ile_drogich}")

