    stan -= 4
    print("Zostało:", stan)

def brutto(netto, vat=23):
    """Zwraca cenę brutto (2 miejsca po przecinku) z ceny netto i stawki VAT w %."""
    return round(netto * (1 + vat / 100), 2)


def czy_parzysta(n):
    """True, gdy n jest parzyste."""
    return n % 2 == 0


def wypisz_brutto(netto):
    print("Brutto:", brutto(netto))


if __name__ == "__main__":
    print(brutto(10), brutto(10, 8), brutto(netto=100, vat=5))
    print(czy_parzysta(4), czy_parzysta(7))
    wynik = wypisz_brutto(20)
    print("Funkcja bez return zwraca:", wynik)

def wydaj(stan, ilosc):
    """Zwraca nowy stan po wydaniu towaru; zła ilość → ValueError."""
    if ilosc <= 0:
        raise ValueError("ilość musi być dodatnia")
    if ilosc > stan:
        raise ValueError(f"brak towaru: na stanie {stan}")
    return stan - ilosc


for wpis in ["5", "dwa", "0", "200"]:
    try:
        ilosc = int(wpis)
        nowy = wydaj(120, ilosc)
    except ValueError as e:
        print(f"{wpis!r}: błąd — {e}")
    else:
        print(f"{wpis!r}: wydano, zostało {nowy}")
    finally:
        print("---")

